    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // unless the bin becomes exactly full (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // 2. Lookahead coupling: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Density balancing: If this bin's residual is significantly higher than the global mean,
    // we want to use it to bring it closer to the average, otherwise preserve tight bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // 4. Scarcity avoidance: If this is the last fitting bin, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New bin threshold: If evaluating an empty bin, add a base penalty to prevent 
    // fragmenting space early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Harmonic class smoothing: Apply a non-linear penalty to residuals that are 
    // multiples of small integers, which often lead to wasted space in future steps.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize unusable small gaps (Dead Space Avoidance)
    // If a gap is created that is too small for any likely future item (e.g., < 10), 
    // it is highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization (k=2)
    // If the next item cannot fit into this post_residual, penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open Bin Pressure
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the current fitting options are extremely poor (high post_residuals).
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 45.0;
        // Reduce cost if we have many open bins already (to avoid fragmentation)
        score -= (open_bins_count as f64 * 0.5);
    } else {
        // Encourage filling existing bins to keep open_bins_count low
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Fitting Constraint
    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If next_item can fit in post_residual, reward this bin heavily.
    // This effectively implements a Best-Fit-Decreasing style pairing strategy.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Further reward if this placement makes the bin residual very tight for the next item
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // 3. Prevent opening new bins prematurely:
    // If this is an empty bin (new bin candidate), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we have very few open bins, opening a new one is less catastrophic.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Global balance: If the post_residual is significantly lower than the mean_residual of other bins,
    // we are making this bin "denser" than average, which is usually good.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 5. Critical thresholding: If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress weighting: As the stream nears completion, become more aggressive about consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // The core strategy is Best-Fit Decreasing logic (minimizing post_residual), 
    // but with penalties for leaving "dead space" that is too small for common items.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (unusable space).
    // If post_residual is small but > 0, it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization:
    // If a next_item exists, penalize bins that can't fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that are perfectly sized for the predicted next item.
            if (post_residual as i32 - next_item_size as i32).abs() < 5 {
                score -= 10.0;
            }
        }
    }

    // 3. Global state balancing:
    // Avoid opening new bins unless necessary. If bin_residual == bin_capacity, 
    // this is a candidate for a new bin. Penalize it heavily unless open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 40.0; // High barrier to opening a new bin
        score -= (open_bins_count as f64 * 0.5); // Slightly reduce barrier if we have many bins
    }

    // 4. Dynamic time horizon:
    // As the stream nears the end, become more aggressive about filling existing bins 
    // to avoid leaving leftovers.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 5. Fitting constraint:
    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean residual feedback:
    // Penalize bins that deviate too far from the average packing density to keep bins uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it's highly likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item is large, penalize small post_residuals 
    // that prevent the next item from fitting in this bin.
    if next_item_size > 0 {
        let fit_penalty = if post < next_item_size as f64 { 15.0 } else { 0.0 };
        score += fit_penalty * (1.0 - progress);
    }

    // Progression scaling: As the stream nears the end, become more aggressive 
    // at filling existing bins to prevent leaving bins partially empty.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // New bin logic: If this is an empty bin (bin_residual == bin_capacity),
    // calculate a "cost" to open it. We only open if the score is lower than 
    // the best existing bin's score.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high, but decreases as we want to 
        // avoid crowding if we have many bins already.
        score = 45.0 + (mean_residual * 0.5) + (progress * 10.0);
    } else {
        // Reward bins that have residuals close to the mean_residual to keep 
        // bin utilization levels balanced (avoids creating one very full and one very empty bin).
        let balance_factor = (post - mean_residual).abs();
        score -= balance_factor * 0.1;
    }

    score
}

