    // 1. Best Fit Decreasing (BFD) core: lower post_residual is better.
    // 2. Harmonic penalty: penalize small remainders that cannot fit common item sizes (10-30).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0; 
    }

    // 3. Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that maintain perfect "fit" for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 4. Harmonic classes: favor filling bins to specific modular thresholds (e.g., 25, 50, 75).
    // This helps group items of similar sizes together.
    let residual_mod = post_residual % 25;
    score += residual_mod as f64 * 0.8;

    // 5. Threshold for opening new bins:
    // If this is the new bin candidate (residual == capacity), apply a penalty based on
    // how many bins are already open and how much space is currently wasted.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open but they are all very full.
        // Otherwise, prioritize fitting into an existing bin.
        score += (open_bins_count as f64 * 5.0) + (100.0 - mean_residual);
    } else {
        // If it's the last chance (only one bin fits), make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Progressive scaling: as the stream nears the end, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

