pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items)
    // Residuals in the range [1, 9] are toxic as the minimum item size is likely > 1.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Dynamic Threshold for New Bin Creation:
    // If we are late in the stream, be more aggressive with packing (lower scores for tight fits).
    // If we are early, be more conservative to avoid stranding items.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty decreases as the number of open bins increases (to avoid fragmentation)
        // and increases as we reach the end of the stream (to force consolidation).
        score = 45.0 + (progress * 20.0) - (open_bins_count as f64 * 0.5);
    } else {
        // This is an existing bin.
        // Reward bins that have residuals close to the global mean to maintain uniformity.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Final adjustment: Prefer keeping residuals large enough for future items (Best Fit Decreasing influence).
    // Smaller post_residual is usually good (Best Fit), but we balance it against the penalty in step 1.
    score
}
